import os
for r,d,f in os.walk('studies'):
 print(r, f)

import glob,gzip
for f in sorted(glob.glob('studies/data/raw/*matrix*')):
 print('\nFILE',f)
 with gzip.open(f,'rt') as h:
  for l in h:
   if l.startswith(('!Sample_title','!Sample_geo_accession','!Sample_source_name','!Sample_characteristics')): print(l.strip())

import glob,gzip,csv,collections
for f in sorted(glob.glob('studies/data/raw/*matrix*')):
 print('\nFILE',f)
 with gzip.open(f,'rt') as h:
  for l in h:
   if l.startswith(('!Sample_title','!Sample_source_name','!Sample_characteristics','!Sample_geo_accession')):
    r=next(csv.reader([l],delimiter='\t')); c=collections.Counter(r[1:]);print(r[0], 'n=',len(r)-1,dict(c) if len(c)<30 else '(many unique)')

